class Solution {
public:
    string findValidPair(string s) {
        int c[10] = {0};
        for (char ch : s) c[ch - '0']++;
        for (int i = 0; i + 1 < s.size(); i++) {
            int a = s[i]-'0', b = s[i+1]-'0';
            if (a != b && c[a] == a && c[b] == b) return s.substr(i, 2);
        }
        return "";
    }
};

