class Solution {
    public String findValidPair(String s) {
        int[] c = new int[10];
        for (char ch : s.toCharArray()) c[ch - '0']++;
        for (int i = 0; i + 1 < s.length(); i++) {
            int a = s.charAt(i) - '0', b = s.charAt(i + 1) - '0';
            if (a != b && c[a] == a && c[b] == b) return s.substring(i, i + 2);
        }
        return "";
    }
}

